13:     /// <summary>
14: 	/// 	Responsible for parsing an string from an ini file, and creating
15: 	/// 	an <see cref="IniData"/> structure.
16: 	/// </summary>
17:     public partial class IniDataParser
18:     {
19:         #region Initialization
20:         /// <summary>
21:         ///     Ctor
22:         /// </summary>
23:         public IniDataParser()
24:         {
25:             Scheme = new IniScheme();
26:             Configuration = new IniParserConfiguration();
27:             _errorExceptions = new List<Exception>();
28:         }
29: 
30:         #endregion
