41:         /// <summary>
42:         /// True is the parsing operation encounter any problem
43:         /// </summary>
44:         public bool HasError { get { return _errorExceptions.Count > 0; } }
45: 
46:         /// <summary>
47:         /// Returns the list of errors found while parsing the ini file.
48:         /// </summary>
49:         /// <remarks>
50:         /// If the configuration option ThrowExceptionOnError is false it
51:         /// can contain one element for each problem found while parsing;
52:         /// otherwise it will only contain the very same exception that was
53:         /// raised.
54:         /// </remarks>
55:         public ReadOnlyCollection<Exception> Errors
56:         {
57:             get { return _errorExceptions.AsReadOnly(); }
58:         }
59:         #endregion
