61:         /// <summary>
62:         ///     Parses a string containing valid ini data
63:         /// </summary>
64:         /// <param name="iniString">
65:         ///     String with data in INI format
66:         /// </param>
67:         public IniData Parse(string iniString)
68:         {
69:             return Parse(new StringReader(iniString));
70:         }
71: 
72:         /// <summary>
73:         ///     Parses a string containing valid ini data
74:         /// </summary>
75:         /// <param name="textReader">
76:         ///     Text reader for the source string contaninig the ini data
77:         /// </param>
78:         /// <returns>
79:         ///     An <see cref="IniData"/> instance containing the data readed
80:         ///     from the source
81:         /// </returns>
82:         /// <exception cref="ParsingException">
83:         ///     Thrown if the data could not be parsed
84:         /// </exception>
85:         public IniData Parse(TextReader textReader)
86:         {
87:             IniData iniData = Configuration.CaseInsensitive ?
88:                   new IniDataCaseInsensitive(Scheme)
89:                   : new IniData(Scheme);
90: 
91:             Parse(textReader, ref iniData);
92: 
93:             return iniData;
94:         }
95: 
96:         /// <summary>
97:         ///     Parses a string containing valid ini data
98:         /// </summary>
99:         /// <param name="textReader">
100:         ///     Text reader for the source string contaninig the ini data
101:         /// </param>
102:         /// <returns>
103:         ///     An <see cref="IniData"/> instance containing the data readed
104:         ///     from the source
105:         /// </returns>
106:         /// <exception cref="ParsingException">
107:         ///     Thrown if the data could not be parsed
108:         /// </exception>       
109:         public void Parse(TextReader textReader, ref IniData iniData)
110:         {
111:             iniData.Clear();
112: 
113:             iniData.Scheme = Scheme.DeepClone();
114: 
115:             _errorExceptions.Clear();
116:             if (Configuration.ParseComments)
117:             {
118:                 CurrentCommentListTemp.Clear();
119:             }
120:             _currentSectionNameTemp = null;
121:             _mBuffer.Reset(textReader);
122:             _currentLineNumber = 0;
123: 
124:             while (_mBuffer.ReadLine())
125:             {
126:                 _currentLineNumber++;
127: 
128:                 try
129:                 {
130:                     ProcessLine(_mBuffer, iniData);
131:                 }
132:                 catch (Exception ex)
133:                 {
134:                     _errorExceptions.Add(ex);
135:                     if (Configuration.ThrowExceptionsOnError)
136:                     {
137:                         throw;
138:                     }
139:                 }
140:             }
141: 
142:             // TODO: is this try necessary?
143:             try
144:             {
145:                 // Orphan comments, assing to last section/key value
146:                 if (Configuration.ParseComments && CurrentCommentListTemp.Count > 0)
147:                 {
148:                     if (iniData.Sections.Count > 0)
149:                     {
150:                         // Check if there are actually sections in the file
151:                         var sections = iniData.Sections;
152:                         var section = sections.FindByName(_currentSectionNameTemp);
153:                         section.Comments.AddRange(CurrentCommentListTemp);
154:                     }
155:                     else if (iniData.Global.Count > 0)
156:                     {
157:                         // No sections, put the comment in the last key value pair
158:                         // but only if the ini file contains at least one key-value pair
159:                         iniData.Global.GetLast().Comments.AddRange(CurrentCommentListTemp);
160:                     }
161: 
162:                     CurrentCommentListTemp.Clear();
163:                 }
164: 
165:             }
166:             catch (Exception ex)
167:             {
168:                 _errorExceptions.Add(ex);
169:                 if (Configuration.ThrowExceptionsOnError)
170:                 {
171:                     throw;
172:                 }
173:             }
174: 
175:             if (HasError)
176:             {
177:                 iniData.Clear();
178:             }
179:         }
