181:         #region Template Method Design Pattern
182:         // All this methods controls the parsing behaviour, so it can be
183:         // modified in derived classes.
184:         // See http://www.dofactory.com/Patterns/PatternTemplate.aspx for an
185:         // explanation of this pattern.
186:         // Probably for the most common cases you can change the parsing
187:         // behavior using a custom configuration object rather than creating
188:         // derived classes.
189:         // See IniParserConfiguration interface, and IniDataParser constructor
190:         // to change the default configuration.
191: 
192:   
193: 
194:         /// <summary>
195:         ///     Processes one line and parses the data found in that line
196:         ///     (section or key/value pair who may or may not have comments)
197:         /// </summary>
198:         protected virtual void ProcessLine(StringBuffer currentLine,
199:                                            IniData iniData)
200:         {
201:             if (currentLine.IsEmpty || currentLine.IsWhitespace) return;
202: 
203:             // TODO: change this to a global (IniData level) array of comments
204:             // Extract comments from current line and store them in a tmp list
205: 
206:             if (ProcessComment(currentLine)) return;
207: 
208:             if (ProcessSection(currentLine, iniData)) return;
209: 
210:             if (ProcessProperty(currentLine, iniData)) return;
211: 
212:             if (Configuration.SkipInvalidLines) return;
213: 
214:             var errorFormat = "Couldn't parse text: '{0}'. Please see configuration option {1}.{2} to ignore this error.";
215:             var errorMsg = string.Format(errorFormat,
216:                                          currentLine,
217:                                          nameof(Configuration),
218:                                          nameof(Configuration.SkipInvalidLines));
219: 
220:             throw new ParsingException(errorMsg,
221:                                        _currentLineNumber,
222:                                        currentLine.DiscardChanges().ToString());
223:         }
224: 
225:         protected virtual bool ProcessComment(StringBuffer currentLine)
226:         {
227:             // Line is  med when it came here, so we only need to check if
228:             // the first characters are those of the comments
229:             var currentLineTrimmed = currentLine.SwallowCopy();
230:             currentLineTrimmed.TrimStart();
231: 
232:             if (!currentLineTrimmed.StartsWith(Scheme.CommentString))
233:             {
234:                 return false;
235:             }
236: 
237:             if (!Configuration.ParseComments)
238:             {
239:                 return true;
240:             }
241: 
242:             currentLineTrimmed.TrimEnd();
243: 
244:             var commentRange = currentLineTrimmed.FindSubstring(Scheme.CommentString);
245:             // Exctract the range of the string that contains the comment but not
246:             // the comment delimiter
247:             var startIdx = commentRange.start + Scheme.CommentString.Length;
248:             var size = currentLineTrimmed.Count - Scheme.CommentString.Length;
249:             var range = Range.FromIndexWithSize(startIdx, size);
250: 
251:             var comment = currentLineTrimmed.Substring(range);
252:             if (Configuration.TrimComments)
253:             {
254:                 comment.Trim();
255:             }
256:             
257:             CurrentCommentListTemp.Add(comment.ToString());
258: 
259:             return true;
260:         }
261: 
262:         /// <summary>
263:         ///     Proccess a string which contains an ini section.%
264:         /// </summary>
265:         /// <param name="currentLine">
266:         ///     The string to be processed
267:         /// </param>
268:         protected virtual bool ProcessSection(StringBuffer currentLine, IniData iniData)
269:         {
270:             if (currentLine.Count <= 0) return false;
271: 
272:             var sectionStartRange = currentLine.FindSubstring(Scheme.SectionStartString);
273: 
274:             if (sectionStartRange.IsEmpty) return false;
275:             
276:             var sectionEndRange = currentLine.FindSubstring(Scheme.SectionEndString, sectionStartRange.size);
277:             if (sectionEndRange.IsEmpty)
278:             {
279:                 if (Configuration.SkipInvalidLines) return false;
280: 
281: 
282:                 var errorFormat = "No closing section value. Please see configuration option {0}.{1} to ignore this error.";
283:                 var errorMsg = string.Format(errorFormat,
284:                                              nameof(Configuration),
285:                                              nameof(Configuration.SkipInvalidLines));
286: 
287:                 throw new ParsingException(errorMsg,
288:                                            _currentLineNumber,
289:                                            currentLine.DiscardChanges().ToString());
290:             }
291: 
292:             var startIdx = sectionStartRange.start + Scheme.SectionStartString.Length;
293:             var endIdx = sectionEndRange.end - Scheme.SectionEndString.Length;
294:             currentLine.ResizeBetweenIndexes(startIdx, endIdx);
295: 
296:             if (Configuration.TrimSections)
297:             {
298:                 currentLine.Trim();
299:             }
300: 
301:             var sectionName = currentLine.ToString();
302: 
303:             // Temporally save section name.
304:             _currentSectionNameTemp = sectionName;
305: 
306:             //Checks if the section already exists
307:             if (!Configuration.AllowDuplicateSections)
308:             {
309:                 if (iniData.Sections.Contains(sectionName))
310:                 {
311:                     if (Configuration.SkipInvalidLines) return false;
312: 
313:                     var errorFormat = "Duplicate section with name '{0}'. Please see configuration option {1}.{2} to ignore this error.";
314:                     var errorMsg = string.Format(errorFormat,
315:                                                  sectionName,
316:                                                  nameof(Configuration),
317:                                                  nameof(Configuration.SkipInvalidLines));
318: 
319:                     throw new ParsingException(errorMsg,
320:                                                _currentLineNumber,
321:                                                currentLine.DiscardChanges().ToString());
322:                 }
323:             }
324: 
325:             // If the section does not exists, add it to the ini data
326:             iniData.Sections.Add(sectionName);
327: 
328:             // Save comments read until now and assign them to this section
329:             if (Configuration.ParseComments)
330:             {
331:                 var sections = iniData.Sections;
332:                 var sectionData = sections.FindByName(sectionName);
333:                 sectionData.Comments.AddRange(CurrentCommentListTemp);
334:                 CurrentCommentListTemp.Clear();
335:             }
336: 
337:             return true;
338:         }
339: 
340:         protected virtual bool ProcessProperty(StringBuffer currentLine, IniData iniData)
341:         {
342:             if (currentLine.Count <= 0) return false;
343: 
344:             var propertyAssigmentIdx = currentLine.FindSubstring(Scheme.PropertyAssigmentString);
345: 
346:             if (propertyAssigmentIdx.IsEmpty) return false;
347: 
348:             var keyRange = Range.WithIndexes(0, propertyAssigmentIdx.start - 1);
349:             var valueStartIdx = propertyAssigmentIdx.end + 1;
350:             var valueSize = currentLine.Count - propertyAssigmentIdx.end - 1;
351:             var valueRange = Range.FromIndexWithSize(valueStartIdx, valueSize);
352: 
353:             var key = currentLine.Substring(keyRange);
354:             var value = currentLine.Substring(valueRange);
355: 
356:             if (Configuration.TrimProperties)
357:             {
358:                 key.Trim();
359:                 value.Trim();
360:             }
361: 
362:             if (key.IsEmpty)
363:             {
364:                 if (Configuration.SkipInvalidLines) return false;
365: 
366:                 var errorFormat = "Found property without key. Please see configuration option {0}.{1} to ignore this error";
367:                 var errorMsg = string.Format(errorFormat,
368:                                              nameof(Configuration),
369:                                              nameof(Configuration.SkipInvalidLines));
370: 
371:                 throw new ParsingException(errorMsg,
372:                                            _currentLineNumber,
373:                                            currentLine.DiscardChanges().ToString());
374:             }
375: 
376:             // Check if we haven't read any section yet
377:             if (string.IsNullOrEmpty(_currentSectionNameTemp))
378:             {
379:                 if (!Configuration.AllowKeysWithoutSection)
380:                 {
381:                     var errorFormat = "Properties must be contained inside a section. Please see configuration option {0}.{1} to ignore this error.";
382:                     var errorMsg = string.Format(errorFormat,
383:                                                 nameof(Configuration),
384:                                                 nameof(Configuration.AllowKeysWithoutSection));
385: 
386:                     throw new ParsingException(errorMsg,
387:                                                _currentLineNumber,
388:                                                currentLine.DiscardChanges().ToString());
389:                 }
390: 
391:                 AddKeyToKeyValueCollection(key.ToString(), 
392:                                            value.ToString(),
393:                                            iniData.Global, 
394:                                            "global");
395:             }
396:             else
397:             {
398:                 var currentSection = iniData.Sections.FindByName(_currentSectionNameTemp);
399: 
400:                 AddKeyToKeyValueCollection(key.ToString(),
401:                                            value.ToString(), 
402:                                            currentSection.Properties,
403:                                            _currentSectionNameTemp);
404:             }
405: 
406: 
407:             return true;
408:         }
